def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

sum_of_primes = 0
n = 1

while True:
    k = (n ** 2) // 5

    if is_prime(k):
