syntax = "proto3";

// 导入其他proto文件
import "google/protobuf/wrappers.proto";
import "google/protobuf/timestamp.proto";

message ExampleMessage {
    // 字段前缀为'optional'表示可选字段
    optional string name = 1;
    repeated int32 numbers = 2;
    google.protobuf.Timestamp datetime = 3;

    // 字段可以包含各种.proto导入的类型
    google.protobuf.DoubleValue double_field = 4;

    // 包含其他消息类型的字段
    User user_info = 5;

    // 一些内置字段类型
    bool is_active = 7;
    int32 age = 8 [default = 0];
    string address = 9;

    // 复用的Oneof类型的枚举
    enum IsActiveEnum {
        FALSE = 0;
        TRUE = 1;
    }
    oneof active_status {
        bool active_bool = 10;
        IsActiveEnum active_enum = 11;
    }

    // 可选的切片（Slice）类型
    repeated bytes binary_data = 12;
}

// 定义用户信息的消息结构
message User {
    string username = 1;
    repeated string interests = 2;

    bool is_verified = 3 [default = false];
}
```

